use crate::resources::Material;use crate::state::{AffinityResponses,Environment,Organism,PropertyDeviations,ResourceObservation,DESIRABILITY_AMOUNT_HALF_SATURATION,DESIRABILITY_MAX};
pub(crate)const DISCRETE_PERCEPTION_THRESHOLD:f64=5.0;
impl crate::state::Simulation{
pub(crate)fn perceived_amount(material:&Material,sensory_resolution:f64)->f64{let amount=material.total_amount().max(0.0);if material.is_structured(){return(amount*sensory_resolution).max(0.0)}if amount<DISCRETE_PERCEPTION_THRESHOLD{(amount.floor()*sensory_resolution.max(0.0)).floor()}else{amount*sensory_resolution}}
pub(crate)fn calculate_property_deviations(p:&crate::resources::ResourceProperties,b:&crate::resources::ResourceBaselines,r:&crate::resources::ResourceProperties)->PropertyDeviations{PropertyDeviations{mass:((p.mass-b.mass)/r.mass).clamp(-1.0,1.0),potential_energy:((p.potential_energy-b.potential_energy)/r.potential_energy).clamp(-1.0,1.0),reactivity:((p.reactivity-b.reactivity)/r.reactivity).clamp(-1.0,1.0),cohesion:((p.cohesion-b.cohesion)/r.cohesion).clamp(-1.0,1.0)}}
pub(crate)fn affinity_response(d:f64,a:f64)->f64{(d*a*3.0).tanh()}pub(crate)fn amount_factor(a:f64)->f64{let a=a.max(0.0);a/(a+DESIRABILITY_AMOUNT_HALF_SATURATION)}pub(crate)fn energy_need_factor(e:f64)->f64{1.0/(1.0+e.max(0.0))}
pub(crate)fn calculate_desirability(o:&Organism,p:&crate::resources::ResourceProperties,amount:f64,b:&crate::resources::ResourceBaselines,r:&crate::resources::ResourceProperties)->(PropertyDeviations,AffinityResponses,f64,f64,f64,f64){let d=Self::calculate_property_deviations(p,b,r);let a=AffinityResponses{mass:Self::affinity_response(d.mass,o.genome.mass_affinity()),potential_energy:Self::affinity_response(d.potential_energy,o.genome.potential_energy_affinity()),reactivity:Self::affinity_response(d.reactivity,o.genome.reactivity_affinity()),cohesion:Self::affinity_response(d.cohesion,o.genome.cohesion_affinity())};let need=Self::energy_need_factor(o.usable_energy);let er=a.potential_energy*(1.0+need);let base=(a.mass+er+a.reactivity+a.cohesion)/4.0;let af=Self::amount_factor(amount);(d,a,base,af,need,(base*af).clamp(-DESIRABILITY_MAX,DESIRABILITY_MAX))}
pub(crate)fn update_resource_perception(o:&mut Organism,e:&Environment){let radius=o.genome.perception_radius();let sr=o.genome.sensory_resolution();let dr=o.genome.directional_resolution();let(px,py)=(o.occupied_cells[0].x,o.occupied_cells[0].y);o.resource_sense.sensed_resources.clear();o.resource_sense.direction_x=0.0;o.resource_sense.direction_y=0.0;o.resource_sense.direction_strength=0.0;let b=crate::resources::ResourceBaselines::from_catalog(&e.catalog);let r=crate::resources::property_ranges(&e.catalog);for i in e.field.cells_within_radius(px,py,radius){let(cx,cy)=e.field.cell_center(i);let(dx,dy)=(cx-px,cy-py);let distance=dx.hypot(dy);let(ux,uy)=if distance>0.0{(dx/distance,dy/distance)}else{(0.0,0.0)};for m in &e.field.cells[i].materials{let amount=Self::perceived_amount(m,sr);if amount<=0.0{continue}let properties=m.weighted_properties(&e.catalog);let(d,a,base,af,need,des)=Self::calculate_desirability(o,&properties,amount,&b,&r);let label=if let Some(s)=m.structure(){s.constituents.iter().map(|c|c.resource.as_str()).collect::<Vec<_>>().join("+")}else{m.composition().iter().map(|c|c.resource.as_str()).collect::<Vec<_>>().join("+")};o.resource_sense.sensed_resources.push(ResourceObservation{name:label,properties,perceived_amount:amount,deviations:d,affinity_responses:a,base_desirability:base,amount_factor:af,potential_energy_need_factor:need,desirability:des,distance,source_x:cx,source_y:cy,field_index:i});o.resource_sense.direction_x+=ux*des;o.resource_sense.direction_y+=uy*des}}let magnitude=(o.resource_sense.direction_x*o.resource_sense.direction_x+o.resource_sense.direction_y*o.resource_sense.direction_y).sqrt();o.resource_sense.direction_strength=magnitude;if magnitude<=f64::EPSILON{return}o.resource_sense.direction_x/=magnitude;o.resource_sense.direction_y/=magnitude;let angle=o.resource_sense.direction_y.atan2(o.resource_sense.direction_x);let steps=(dr.max(0.001)*32.0).max(1.0);let step=std::f64::consts::TAU/steps;let q=(angle/step).round()*step;o.resource_sense.direction_x=q.cos();o.resource_sense.direction_y=q.sin()}}
